// SPDX-License-Identifier: MIT
// Host test for Darwin contiguous-VA composite BO.
// Runs the REAL extracted production functions (see composite_production.inc,
// generated by mesa-patches/test-composite-bo.py via brace-matched extraction
// from PATCHED_MESA/src/amd/vulkan/winsys/amdgpu/radv_amdgpu_bo.c and
// radv_amdgpu_cs.c). Stubs cover only external ac_drm_* transport, VA/physical
// allocators, and Mesa util/types/constants. No algorithm is re-implemented:
// every behavior under test executes production code; the harness only records
// what production asked the (fake) kernel to do.
#ifndef HAVE_AMDGPU_DARWIN
#define HAVE_AMDGPU_DARWIN 1
#endif
