static inline uint64_t align64(uint64_t v, uint64_t a) {
   assert(a && !(a & (a - 1)));
   return (v + a - 1) & ~(a - 1);
}
// Matches Mesa util/u_math.h semantics for power-of-two inputs used here.
static unsigned util_logbase2(unsigned n) {
   assert(n && !(n & (n - 1)));
   return 31 - __builtin_clz(n);
}
