int ac_drm_va_range_alloc(ac_drm_device *dev, enum amdgpu_gpu_va_range t, uint64_t size,
                          uint64_t align, uint64_t req, uint64_t *out_va,
                          amdgpu_va_handle *out_h, uint64_t flags) {
   (void)dev; (void)t; (void)align; (void)req; (void)flags;
   if (g_fail_va_alloc) return -ENOMEM;
   struct fake_va *v = calloc(1, sizeof(*v));
   if (!v) return -ENOMEM;
   // Deterministic base; production must use exactly one reservation per parent.
   v->base = g_va_base;
   v->size = size;
   *out_va = v->base;
   *out_h = v;
   g_parent_va = v->base;
   g_parent_handle = v;
   g_last_va_size = size;
   g_last_va_align = align;
   g_va_alloc_count++;
   return 0;
}
int ac_drm_va_range_free(amdgpu_va_handle h) {
   g_va_free_count++;
   free(h);
   return 0;
}
int ac_drm_bo_alloc(ac_drm_device *dev, struct amdgpu_bo_alloc_request *req, ac_drm_bo *bo) {
   (void)dev;
   if (g_alloc_req_count < ARRAY_SIZE(g_alloc_req_flags))
      g_alloc_req_flags[g_alloc_req_count++] = req->flags;
   g_phys_alloc_attempts++;
   if (g_fail_all_allocs) return g_fail_all_alloc_code ? g_fail_all_alloc_code : -ENOMEM;
   if (g_alloc_fail_at_attempt && g_phys_alloc_attempts == g_alloc_fail_at_attempt)
      return g_alloc_fail_code_at ? g_alloc_fail_code_at : -ENOMEM;
   if (g_fail_alloc_above && req->alloc_size > g_fail_alloc_above) return -ENOMEM;
   struct fake_phys *p = calloc(1, sizeof(*p));
   if (!p) return -ENOMEM;
   p->size = req->alloc_size;
   p->handle = g_next_kms_handle++;
   bo->abo = p;
   g_phys_alloc_count++;
   return 0;
}
int ac_drm_bo_export(ac_drm_device *dev, ac_drm_bo bo, enum amdgpu_bo_handle_type type,
                     uint32_t *h) {
   (void)dev; (void)type;
   g_export_count++;
   if (g_fail_export_next) {
      g_fail_export_next = false;
      return g_export_fail_code ? g_export_fail_code : -ENOMEM;
   }
   struct fake_phys *p = (struct fake_phys *)bo.abo;
   *h = p->handle;
   return 0;
}
int ac_drm_bo_free(ac_drm_device *dev, ac_drm_bo bo) {
   (void)dev;
   if (g_fail_free_next) {
      // Boundary fake: reclaim the stub backing so the sanitizer run stays
      // leak-free; the actual kernel may quarantine instead of physically
      // freeing. Production must keep going (log it) and still release the
      // VA/tracker, which the test verifies.
      g_fail_free_next = false;
      free(bo.abo);
      return g_free_fail_code ? g_free_fail_code : -EIO;
   }
   g_phys_free_count++;
   free(bo.abo);
   return 0;
}
int ac_drm_bo_va_op_raw(ac_drm_device *dev, uint32_t h, uint64_t off, uint64_t size,
                        uint64_t addr, uint64_t flags, uint32_t ops) {
   (void)dev;
   if (ops != AMDGPU_VA_OP_MAP && ops != AMDGPU_VA_OP_UNMAP) {
      fprintf(stderr, "unexpected VA op %u (only MAP/UNMAP allowed)\n", ops);
      ++g_failures;
      return -EINVAL;
   }
   if (ops == AMDGPU_VA_OP_MAP) {
      if (g_map_recs < ARRAY_SIZE(g_maps)) {
         g_maps[g_map_recs] = (struct map_rec){h, off, size, addr, ops};
         g_map_flags[g_map_recs] = flags;
         g_map_recs++;
      }
      g_map_count++;
      if (g_map_fail_at && g_map_count == g_map_fail_at &&
          (!g_map_fail_addr || g_map_fail_addr == addr))
         return g_map_fail_code ? g_map_fail_code : -ENOMEM;
   } else {
      if (g_fail_unmap_next) {
         g_fail_unmap_next = false;
         g_unmap_count++;
         if (g_unmap_recs < ARRAY_SIZE(g_unmaps))
            g_unmaps[g_unmap_recs++] = (struct map_rec){h, off, size, addr, ops};
         return g_unmap_fail_code ? g_unmap_fail_code : -EIO;
      }
      g_unmap_count++;
      if (g_unmap_recs < ARRAY_SIZE(g_unmaps))
         g_unmaps[g_unmap_recs++] = (struct map_rec){h, off, size, addr, ops};
   }
   return 0;
}
int ac_drm_bo_va_op_raw2(ac_drm_device *dev, uint32_t h, uint64_t off, uint64_t size,
                         uint64_t addr, uint64_t flags, uint32_t ops, uint32_t s,
                         uint64_t p, uint64_t f1, uint32_t nf) {
   (void)dev; (void)h; (void)off; (void)size; (void)addr; (void)flags; (void)ops;
   (void)s; (void)p; (void)f1; (void)nf;
   g_raw2_called = true;
   return -EINVAL;
}
int ac_drm_cs_syncobj_timeline_wait(ac_drm_device *dev, uint32_t *hs, uint64_t *pts,
                                   unsigned n, int64_t t, unsigned f, uint32_t *s) {
   (void)dev; (void)hs; (void)pts; (void)n; (void)t; (void)f; (void)s;
   return 0;
}
int ac_drm_bo_cpu_map(ac_drm_device *dev, ac_drm_bo bo, void **cpu) {
   (void)dev; (void)bo;
   g_cpu_map_count++;
   *cpu = g_cpu_backing;
   return 0;
}
int ac_drm_bo_cpu_unmap(ac_drm_device *dev, ac_drm_bo bo) {
   (void)dev; (void)bo;
   g_cpu_unmap_count++;
   return 0;
}
int ac_drm_bo_set_metadata(ac_drm_device *dev, uint32_t h, struct amdgpu_bo_metadata *md) {
   (void)dev;
   if (g_setmeta_count < ARRAY_SIZE(g_setmeta_handles)) {
      g_setmeta_handles[g_setmeta_count] = h;
      g_setmeta_tilings[g_setmeta_count] = md->tiling_info;
      g_setmeta_count++;
   }
   return 0;
}
int ac_drm_bo_query_info(ac_drm_device *dev, uint32_t h, struct amdgpu_bo_info *info) {
   (void)dev;
   if (g_query_count < ARRAY_SIZE(g_query_handles))
      g_query_handles[g_query_count++] = h;
   memset(info, 0, sizeof(*info));
   // Handle-derived contents: lets the test prove the parent delegates to
   // the first child (identical decode) rather than any other BO.
   info->metadata.tiling_info = (uint64_t)h * 2654435761ull + 0x12345ull;
   info->metadata.size_metadata = h & 0xffff;
   for (unsigned i = 0; i < ARRAY_SIZE(info->metadata.umd_metadata); i++)
      info->metadata.umd_metadata[i] = (uint32_t)(h ^ (0x5a5a5a5a + i));
   return 0;
}
